// ====================================================================
// COMPOSE NOTIF  -- GLOBAL (menggantikan 2 notifier per-klien)
// --------------------------------------------------------------------
// Menambah klien ke-3 = tambah 1 entri di TENANTS + 1 baris di WF_MAP.
// Node lain tidak perlu disentuh.
// ====================================================================
const DASH = 'https://n8n.chatminagent.workers.dev';

// device_id menentukan perangkat WA pengirim. Dibedakan per tenant supaya
// perilakunya persis sama dengan 2 notifier lama yang digantikan.
const TENANTS = {
  'VIRA-TS':     { label: 'The Scholars',             device_id: 'D-4ZV1F' },
  'VIRA-PCR':    { label: 'Persada Cisoka Residence', device_id: 'D-LM6WE' },
  'VIRA-GLOBAL': { label: 'Global / lintas klien',    device_id: 'D-4ZV1F' },
};

// Pemetaan utama: workflow id -> tenant. Dipakai lebih dulu karena beberapa
// nama workflow tidak mengandung kata kunci tenant sama sekali
// (mis. "Topic Harvester (WF-A)" milik TS, "Follow-up AI Powered" milik PCR).
const WF_MAP = {
  '27Nw6efKWq3Pq-J1T2Z2w': 'VIRA-TS',  // VIRA TS (main)
  '53SnbaFfbxETx7KvUw6_U': 'VIRA-TS',  // Topic Harvester (WF-A)
  '49Idh3Um3-OiK2eKlBcCi': 'VIRA-TS',  // Monthly Rollup (WF-B)
  'flkj_TqYPs350gF3gp74K': 'VIRA-TS',  // STATS Cleanup v3
  'LkpnapMdpbwuwS09mSuEw': 'VIRA-TS',  // MSG_BUFFER Cleanup TS (pensiun setelah migrasi)
  'oCQ315OHAjQEuG2vh14RR': 'VIRA-PCR', // VIRA PCR AI Powered (main)
  'qaux8b14IgvxEXfoUtxa2': 'VIRA-PCR', // Follow-up AI Powered
  'Uqt1M4Soj8gPbSdPBShBX': 'VIRA-PCR', // VIRA-PCR - STATS Purge
  'TIt9Ns4H4B4_6nuzqDRyR': 'VIRA-PCR', // MSG_BUFFER Cleanup PCR (pensiun setelah migrasi)
};

// Cadangan kalau id belum terdaftar (mis. workflow baru yang belum dimasukkan
// ke WF_MAP): tebak dari nama. Kalau tetap tidak ketemu -> VIRA-GLOBAL.
function tebakDariNama(nama) {
  const h = String(nama || '').toLowerCase();
  if (h.indexOf('pcr') !== -1 || h.indexOf('persada') !== -1) return 'VIRA-PCR';
  if (h.indexOf('scholar') !== -1 || h.indexOf('vira ts') !== -1) return 'VIRA-TS';
  return 'VIRA-GLOBAL';
}

const e      = $input.first().json;
const wfId   = e.workflow?.id || '';
const wfName = e.workflow?.name || 'VIRA';
const execId = e.execution?.id || '-';
const node   = e.execution?.error?.node?.name || e.execution?.lastNodeExecuted || '-';
const msg    = (e.execution?.error?.message || 'unknown error').substring(0, 300);
const url    = e.execution?.url || '-';

const tenantId = WF_MAP[wfId] || tebakDariNama(wfName);
const tenant   = TENANTS[tenantId] || TENANTS['VIRA-GLOBAL'];

if (!WF_MAP[wfId]) {
  console.warn('Workflow id ' + wfId + ' (' + wfName + ') belum ada di WF_MAP - tenant ditebak: ' + tenantId);
}

// Link hanya dibuat kalau execution id benar-benar ada. Error Trigger TIDAK
// mengirim execution.id kalau errornya terjadi di node trigger - tanpa penjagaan
// ini, link-nya jadi ".../#/e/-" yang cuma bikin bingung.
const dashUrl = /^\d+$/.test(String(execId)) ? `${DASH}/#/e/${execId}` : '';

const text = `\u{1F6A8} [${tenant.label}] EKSEKUSI GAGAL\nWorkflow: ${wfName}\nNode: ${node}\nError: ${msg}\nExecution: ${execId}`
  + (dashUrl ? `\n\n\u{1F4F1} Retry dari HP:\n${dashUrl}` : '')
  + `\n\n\u{1F5A5}\uFE0F Buka di n8n:\n${url}`
  + `\n\n\u26A0\uFE0F Ada pesan user yang kemungkinan TIDAK terbalas. Cek & balas manual.`;

return [{ json: {
  notif_text:   text,
  tenant_id:    tenantId,
  tenant_label: tenant.label,
  device_id:    tenant.device_id,
} }];

// Kirimi bisa balas HTTP 200 tapi isinya gagal.
// Node ini sengaja throw supaya jalur fallback email ikut jalan.
const input = $input.first();
const r = input.json || {};

const isSuccess = r.status === true ||
                  r.success === true ||
                  (r.data && r.data.id) ||
                  (r.message && r.message !== 'error');

if (!isSuccess) {
  throw new Error('Kirimi API gagal: ' + JSON.stringify(r).slice(0, 500));
}

return [input];

// ============================================================
// Rangkai payload untuk GLOBAL - Email Fallback Notifier
// Dipanggil saat node Kirimi gagal (HTTP error ATAU response gagal)
//
// Beda dari 2 notifier lama: TENANT tidak lagi hardcoded per file,
// tapi diambil dari hasil deteksi di node "Compose Notif".
// ============================================================
const et    = $('Error Trigger').first().json || {};
const comp  = $('Compose Notif').first().json || {};
const notif = comp.notif_text || '';
const f     = $input.first().json || {};

// pesan kegagalan Kirimi (bentuknya beda-beda tergantung jalur error)
const reason = f.error?.message || f.error || f.message ||
               'Kirimi API tidak mengembalikan status sukses';

return [{
  json: {
    source: 'kirimi_fallback',
    tenant: comp.tenant_id || 'VIRA-GLOBAL',

    // isi alert yang gagal terkirim ke WA
    notif_text: notif,

    // kenapa WA-nya gagal
    fail_node: 'Notify Admin Error (Kirimi)',
    fail_reason: String(reason).slice(0, 600),
    kirimi_response: JSON.stringify(f).slice(0, 800),

    // identitas notifier ini
    notifier_wf_name: $workflow.name,
    notifier_wf_id: $workflow.id,
    notifier_exec_id: $execution.id,

    // error aslinya (dari Error Trigger)
    orig_wf_name: et.workflow?.name || '-',
    orig_wf_id: et.workflow?.id || '',
    orig_exec_id: et.execution?.id || '-',
    orig_exec_url: et.execution?.url || '',
    orig_node: et.execution?.error?.node?.name || et.execution?.lastNodeExecuted || '-',
    orig_error: String(et.execution?.error?.message || '-').slice(0, 600)
  }
}];
